-- Six source-backed public incidents, October 22 2026; legal and factual context checked.
-- Modify only unassigned, unanswered cases; no change to option keys or effect scores.
DO $guard$
BEGIN
IF (SELECT count(*) FROM public.event_cases c
 WHERE c.case_key IN ('bank-expanded-serious-05-01','bank-expanded-serious-22-01','bank-curated-serious-02','bank-expanded-serious-07-01','bank-curated-serious-18','bank-expanded-serious-01-01') AND c.status='ready' AND c.source_url IS NULL AND c.verified IS FALSE
 AND NOT EXISTS (SELECT 1 FROM public.event_assignments a WHERE a.case_id=c.id)
 AND NOT EXISTS (SELECT 1 FROM public.event_decisions d WHERE d.case_id=c.id)
 AND NOT EXISTS (SELECT 1 FROM public.event_case_outcomes o WHERE o.case_id=c.id)
 AND NOT EXISTS (SELECT 1 FROM public.event_collaboration_invites x WHERE x.case_id=c.id)
 AND NOT EXISTS (SELECT 1 FROM public.event_discussion_messages x WHERE x.case_id=c.id)
 AND NOT EXISTS (SELECT 1 FROM public.event_authority_evidence x WHERE x.case_id=c.id)
 AND NOT EXISTS (SELECT 1 FROM public.budget_transfer_requests x WHERE x.event_case_id=c.id)
) <> 6 THEN RAISE EXCEPTION 'One of six cases is assigned, altered or already sourced; refusing publication'; END IF;
END $guard$;

DO $case$
BEGIN
 IF NOT EXISTS(SELECT 1 FROM public.event_cases WHERE case_key='bank-expanded-serious-05-01' AND effect_plan->>'best_option_key'='option_1' AND jsonb_array_length(decision_options)=5 AND jsonb_array_length(effect_plan->'options')=5)
 THEN RAISE EXCEPTION 'Choice position unexpectedly changed for bank-expanded-serious-05-01'; END IF;
END $case$;
UPDATE public.event_cases AS c
SET title='Челябинская область: 224 школьника без подвоза из-за неисправных автобусов', situation='22 апреля 2026 года прокуратура Челябинской области сообщила о результатах проверки организации школьных перевозок в Сосновском районе. Поводом стала публикация СМИ о том, что дети из деревень были вынуждены ездить на занятия по очереди из-за поломок школьных автобусов. Проверкой установлено: с 18 февраля по 27 марта 2026 года из-за технических неисправностей четырёх автобусов МОУ «Полетаевская СОШ» был приостановлен подвоз 224 обучающихся из десяти населённых пунктов. Речь идёт о фактически установленном нарушении, а не о предположении, основанном только на жалобе.

Представьте заседание ответственного органа образования после поступления материалов проверки. Перед ним стоит вопрос не о выборе красивой формулировки ответа родителям, а об обеспечении фактической доступности школы. Пока транспорт не выходит на маршрут, детям затруднительно реализовать право на получение образования. Нельзя считать решением простое изменение записи о рейсе в расписании, если технически исправный автобус и водитель отсутствуют. Одновременно нельзя выпускать неисправные машины ради отчёта о восстановлении рейсов: требования безопасности перевозок сохраняются.

Необходимо установить число детей по населённым пунктам и сменам, проверить фактическую исправность транспорта, доступность законных резервных перевозок и наличие квалифицированных водителей. План устранения нарушения должен содержать временную безопасную транспортную схему, ответственных исполнителей и проверку фактического подвоза каждого дня. Бюджетные расходы и договорные отношения оформляются по предусмотренной процедуре.

Статья 40 Федерального закона № 273-ФЗ регулирует транспортное обеспечение обучающихся и обязанности учредителей соответствующих организаций по бесплатной перевозке в предусмотренных случаях. Какой порядок действий устраняет транспортный разрыв без риска для детей и с проверяемым результатом?',
source_url='https://epp.genproc.gov.ru/ru/proc_74/mass-media/news/main/e8471469/',
source_note='Подтверждённые обстоятельства: https://epp.genproc.gov.ru/ru/proc_74/mass-media/news/main/e8471469/; правовое основание: Федеральный закон от 29.12.2012 № 273-ФЗ, статья 40 — организация бесплатной перевозки обучающихся до образовательных организаций и обратно.',
decision_options='["Установить потребность всех десяти населённых пунктов, организовать безопасные временные перевозки исправным транспортом, устранить неисправности, проверить водителей и ежедневно контролировать фактическое исполнение маршрутов.","Временно допустить неисправные автобусы к рейсам при условии уменьшения скорости движения, чтобы не менять школьное расписание.","Разослать родителям сообщение, что отсутствие автобусов является уважительной причиной пропуска занятий, не организуя доступный транспорт.","Перенести решение до подготовки пятилетней программы обновления автопарка, ограничившись просьбой к родителям подвозить детей самостоятельно.","Закупить новые автобусы без проверки возможности временного использования исправных машин и установления финансирования."]'::jsonb,
effect_plan=jsonb_set(c.effect_plan,'{options}',(
 SELECT jsonb_agg(
 jsonb_set(
   jsonb_set(o.item,'{description}',to_jsonb(CASE WHEN o.item->>'key'='option_1' THEN 'Правильная последовательность сочетает немедленное безопасное транспортное обеспечение и устранение причин срыва рейсов. Исправность автобуса и допуск водителя подтверждаются до выхода на маршрут. Учредитель контролирует реальную доступность образования для всех затронутых школьников. Статья 40 закона № 273-ФЗ не позволяет заменить организацию бесплатного подвоза формальными уведомлениями или выпуском опасного транспорта.'::text ELSE ('["Установить потребность всех десяти населённых пунктов, организовать безопасные временные перевозки исправным транспортом, устранить неисправности, проверить водителей и ежедневно контролировать фактическое исполнение маршрутов.","Временно допустить неисправные автобусы к рейсам при условии уменьшения скорости движения, чтобы не менять школьное расписание.","Разослать родителям сообщение, что отсутствие автобусов является уважительной причиной пропуска занятий, не организуя доступный транспорт.","Перенести решение до подготовки пятилетней программы обновления автопарка, ограничившись просьбой к родителям подвозить детей самостоятельно.","Закупить новые автобусы без проверки возможности временного использования исправных машин и установления финансирования."]'::jsonb->>(o.pos::integer-1)) END)),
   '{legal_basis}',to_jsonb('Федеральный закон от 29.12.2012 № 273-ФЗ, статья 40 — организация бесплатной перевозки обучающихся до образовательных организаций и обратно.'::text)
 ) ORDER BY o.pos)
 FROM jsonb_array_elements(c.effect_plan->'options') WITH ORDINALITY AS o(item,pos)
))
WHERE c.case_key='bank-expanded-serious-05-01';

DO $case$
BEGIN
 IF NOT EXISTS(SELECT 1 FROM public.event_cases WHERE case_key='bank-expanded-serious-22-01' AND effect_plan->>'best_option_key'='option_4' AND jsonb_array_length(decision_options)=5 AND jsonb_array_length(effect_plan->'options')=5)
 THEN RAISE EXCEPTION 'Choice position unexpectedly changed for bank-expanded-serious-22-01'; END IF;
END $case$;
UPDATE public.event_cases AS c
SET title='Забайкалье: жалобы на плесень в школьной столовой и проверка питания', situation='3 декабря 2025 года прокуратура Забайкальского края сообщила о проведённой проверке Александрово-Заводской средней школы. Поводом стали публикации в СМИ и жалобы родителей на подачу учащимся еды с плесенью. Прокуратура района привлекла к проверке специалистов Роспотребнадзора. В сообщении надзорного органа речь идёт об устранении нарушений санитарно-эпидемиологических требований при организации школьного питания. Важно различать жалобы о конкретном продукте и подтверждённые результаты проверки: одно только сообщение в социальной сети не заменяет обследование и документы контроля.

Перед руководством школы и учредителем возникает задача обеспечить безопасность питания, не лишая детей предусмотренной законом возможности получать его. Для этого необходимы проверка остатков и партий продуктов, условий хранения, работы пищеблока и документов поставщиков, взаимодействие с санитарными специалистами и фиксация выявленных нарушений. Действия должны быть соразмерны фактическому риску: нельзя продолжать выдачу подозрительной еды, но и бессрочное закрытие всей школы без оценки необходимости не является универсальным решением.

Отдельного рассмотрения требует исполнение контракта на питание. Следует определить, какое лицо отвечает за поставку, приготовление и входной контроль, как документируется несоответствие и на каком основании предъявляются требования поставщику. Родители должны получить достоверное сообщение о мерах безопасности и порядке организации питания, а не обвинения до завершения проверки.

Статья 37 Федерального закона № 273-ФЗ возлагает организацию питания на образовательную организацию. Статья 17 закона № 52-ФЗ требует соблюдать санитарные нормы при приготовлении, хранении и реализации пищи. Как обеспечить оперативную безопасность школьников, надлежащую проверку нарушений и возобновление только безопасного питания?',
source_url='https://epp.genproc.gov.ru/ru/proc_75/mass-media/news/main/e8245653/',
source_note='Подтверждённые обстоятельства: https://epp.genproc.gov.ru/ru/proc_75/mass-media/news/main/e8245653/; правовое основание: Федеральный закон от 29.12.2012 № 273-ФЗ, статья 37, и Федеральный закон от 30.03.1999 № 52-ФЗ, статья 17 — организация питания обучающихся и санитарно-эпидемиологические требования.',
decision_options='["Продолжить выдачу всей поставленной еды, поскольку официального судебного решения о нарушениях поставщика пока нет.","Опубликовать возмущённое заявление в адрес поставщика и объявить его виновным до оформления результатов санитарной проверки.","Временно заменить школьное питание самостоятельными домашними обедами без решения вопроса о предусмотренном бесплатном горячем питании.","Приостановить выдачу продукции с признаками нарушения безопасности, организовать документированную проверку с санитарными специалистами, обеспечить безопасное питание и контроль договора, затем подтвердить устранение нарушений.","Немедленно заключить крупный договор на реконструкцию всей школы без проверки пищеблока, источника продуктов и обязательств действующего подрядчика."]'::jsonb,
effect_plan=jsonb_set(c.effect_plan,'{options}',(
 SELECT jsonb_agg(
 jsonb_set(
   jsonb_set(o.item,'{description}',to_jsonb(CASE WHEN o.item->>'key'='option_4' THEN 'Выбор предупреждает угрозу здоровью и одновременно сохраняет обязанность организовать безопасное питание. Пробы, документы, условия хранения, ответственность поставщика и меры по устранению нарушений фиксируются по результатам компетентной проверки. Статья 37 закона № 273-ФЗ и статья 17 закона № 52-ФЗ не допускают подмены санитарных мер публичными заявлениями.'::text ELSE ('["Продолжить выдачу всей поставленной еды, поскольку официального судебного решения о нарушениях поставщика пока нет.","Опубликовать возмущённое заявление в адрес поставщика и объявить его виновным до оформления результатов санитарной проверки.","Временно заменить школьное питание самостоятельными домашними обедами без решения вопроса о предусмотренном бесплатном горячем питании.","Приостановить выдачу продукции с признаками нарушения безопасности, организовать документированную проверку с санитарными специалистами, обеспечить безопасное питание и контроль договора, затем подтвердить устранение нарушений.","Немедленно заключить крупный договор на реконструкцию всей школы без проверки пищеблока, источника продуктов и обязательств действующего подрядчика."]'::jsonb->>(o.pos::integer-1)) END)),
   '{legal_basis}',to_jsonb('Федеральный закон от 29.12.2012 № 273-ФЗ, статья 37, и Федеральный закон от 30.03.1999 № 52-ФЗ, статья 17 — организация питания обучающихся и санитарно-эпидемиологические требования.'::text)
 ) ORDER BY o.pos)
 FROM jsonb_array_elements(c.effect_plan->'options') WITH ORDINALITY AS o(item,pos)
))
WHERE c.case_key='bank-expanded-serious-22-01';

DO $case$
BEGIN
 IF NOT EXISTS(SELECT 1 FROM public.event_cases WHERE case_key='bank-curated-serious-02' AND effect_plan->>'best_option_key'='option_1' AND jsonb_array_length(decision_options)=6 AND jsonb_array_length(effect_plan->'options')=6)
 THEN RAISE EXCEPTION 'Choice position unexpectedly changed for bank-curated-serious-02'; END IF;
END $case$;
UPDATE public.event_cases AS c
SET title='Сочи: оползень повредил коллектор и создал угрозу жилому дому', situation='8 августа 2024 года прокуратура Центрального района Сочи сообщила об устранении аварийной ситуации в районе улицы Цюрупы. Проверка установила, что оползневые процессы вызвали смещение грунта и повредили проходящий по этой территории коллектор. При комиссионном обследовании обнаружили перелом участка коллектора и изношенные колодцы. Вода выходила на поверхность и подмывала фундамент многоквартирного жилого дома. Таким образом, проблема выходила за пределы отдельной коммунальной неисправности: повреждение инженерной сети было связано с состоянием склона и риском для здания.

Предположим, уполномоченные службы получают такие материалы до полного завершения восстановительных работ. Они должны разграничить несколько направлений: безопасность жильцов, обследование фундамента, ограничение опасного доступа при необходимости, восстановление работы коллектора и проверку грунта. Без технического заключения нельзя утверждать, что здание обязательно подлежит сносу или что угрозы больше нет. Нельзя также считать проблему решённой одним косметическим ремонтом асфальта, пока вода продолжает подмывать основание дома.

Необходимы взаимодействие с эксплуатирующей инженерные сети организацией, собственником или управляющей организацией дома, специалистами по грунтам и компетентным органом местного самоуправления. Если обследование подтвердит угрозу людям, защитные и эвакуационные меры должны приниматься по установленным полномочиям с информированием жильцов. Ремонт и последующий контроль оформляются на основе актов обследования и предусмотренных источников финансирования.

Статья 11 Федерального закона № 68-ФЗ определяет полномочия органов субъектов и местного самоуправления при угрозе чрезвычайных ситуаций. Как прекратить воздействие аварии на дом и обеспечить безопасность граждан до документального подтверждения устойчивости сооружений?',
source_url='https://epp.genproc.gov.ru/ru/proc_23/mass-media/news/regional/e6879561/',
source_note='Подтверждённые обстоятельства: https://epp.genproc.gov.ru/ru/proc_23/mass-media/news/regional/e6879561/; правовое основание: Федеральный закон от 21.12.1994 № 68-ФЗ, статья 11 — полномочия по предупреждению чрезвычайных ситуаций, информированию населения и проведению защитных мероприятий.',
decision_options='["Обеспечить комиссионное техническое обследование и оценку угрозы жильцам, принять соразмерные защитные меры, устранить повреждение коллектора, проконтролировать устойчивость склона и документально подтвердить безопасность дома.","Объявить весь район непригодным для проживания и потребовать немедленного переселения всех жителей без оценки технического состояния и полномочий.","Ограничиться дорожным ремонтом на поверхности, не обследуя повреждённый коллектор и фундамент.","Поручить жильцам самостоятельно ремонтировать коммунальную сеть, даже если им не принадлежат соответствующие инженерные сооружения.","Считать ситуацию безопасной на основании того, что вода временно перестала выходить на поверхность, и отказаться от дальнейших обследований.","Отложить любые защитные меры до появления окончательного проекта капитального ремонта, не обеспечив наблюдение за потенциальной угрозой."]'::jsonb,
effect_plan=jsonb_set(c.effect_plan,'{options}',(
 SELECT jsonb_agg(
 jsonb_set(
   jsonb_set(o.item,'{description}',to_jsonb(CASE WHEN o.item->>'key'='option_1' THEN 'Компетентное решение опирается на обследование инженерной сети, грунта и здания, прекращение опасного воздействия и обеспечение безопасности людей. При подтверждении угрозы органы действуют по статье 11 закона № 68-ФЗ. Массовое переселение без установленных оснований либо ремонт только видимых повреждений не устраняет риск.'::text ELSE ('["Обеспечить комиссионное техническое обследование и оценку угрозы жильцам, принять соразмерные защитные меры, устранить повреждение коллектора, проконтролировать устойчивость склона и документально подтвердить безопасность дома.","Объявить весь район непригодным для проживания и потребовать немедленного переселения всех жителей без оценки технического состояния и полномочий.","Ограничиться дорожным ремонтом на поверхности, не обследуя повреждённый коллектор и фундамент.","Поручить жильцам самостоятельно ремонтировать коммунальную сеть, даже если им не принадлежат соответствующие инженерные сооружения.","Считать ситуацию безопасной на основании того, что вода временно перестала выходить на поверхность, и отказаться от дальнейших обследований.","Отложить любые защитные меры до появления окончательного проекта капитального ремонта, не обеспечив наблюдение за потенциальной угрозой."]'::jsonb->>(o.pos::integer-1)) END)),
   '{legal_basis}',to_jsonb('Федеральный закон от 21.12.1994 № 68-ФЗ, статья 11 — полномочия по предупреждению чрезвычайных ситуаций, информированию населения и проведению защитных мероприятий.'::text)
 ) ORDER BY o.pos)
 FROM jsonb_array_elements(c.effect_plan->'options') WITH ORDINALITY AS o(item,pos)
))
WHERE c.case_key='bank-curated-serious-02';

DO $case$
BEGIN
 IF NOT EXISTS(SELECT 1 FROM public.event_cases WHERE case_key='bank-expanded-serious-07-01' AND effect_plan->>'best_option_key'='option_1' AND jsonb_array_length(decision_options)=6 AND jsonb_array_length(effect_plan->'options')=6)
 THEN RAISE EXCEPTION 'Choice position unexpectedly changed for bank-expanded-serious-07-01'; END IF;
END $case$;
UPDATE public.event_cases AS c
SET title='Орск: защита эвакуированных жителей при паводке 2024 года', situation='9 апреля 2024 года Генеральная прокуратура Российской Федерации сообщила о работе в пунктах временного размещения эвакуированных во время паводка в Оренбургской области. В Орске совместная комиссия проверяла предоставление социальных услуг людям, размещённым на базе школы № 15. Представители прокуратуры взаимодействовали со Сбербанком и отделением Социального фонда России по области по вопросам своевременного перечисления социальных и пенсионных выплат, пособий и получения технических средств реабилитации. Также с МВД и Росгвардией обсуждалось усиление охраны подтопленных территорий для сохранности имущества оставивших дома граждан.

В публикации отдельно отмечено посещение пункта временного размещения на базе больницы Новотроицка. Он предназначался для эвакуированных, которым требовалась специализированная медицинская помощь. Эта деталь подчёркивает: при паводке недостаточно просто вывезти людей из зоны риска и разместить их в одном здании. Разным группам пострадавших могут требоваться медицинское сопровождение, доступное размещение, сохранение социальных выплат, помощь в восстановлении документов и охрана оставленного имущества.

Задача ответственных органов — определить безопасные способы эвакуации по сведениям оперативного штаба, наладить учёт размещённых людей без публичного раскрытия чувствительной информации и организовать межведомственное обслуживание. Решение о технических сооружениях для защиты территории должно опираться на расчёты специалистов; нельзя произвольно изменять направление паводковых вод ради защиты одной улицы с риском для другой.

Статья 11 Федерального закона № 68-ФЗ предусматривает полномочия по эвакуации, информированию и защите граждан при чрезвычайных ситуациях. Как согласовать спасение и размещение людей, медицинскую помощь, социальные выплаты и защиту имущества, не заменяя документированные решения общими обещаниями?',
source_url='https://epp.genproc.gov.ru/ru/gprf/mass-media/news/main/e470391/',
source_note='Подтверждённые обстоятельства: https://epp.genproc.gov.ru/ru/gprf/mass-media/news/main/e470391/; правовое основание: Федеральный закон от 21.12.1994 № 68-ФЗ, статья 11 — эвакуация, информирование, аварийно-спасательные мероприятия и обеспечение защиты населения.',
decision_options='["Согласовать безопасную эвакуацию с оперативным штабом, организовать размещение по потребностям граждан, восстановить доступ к выплатам и медицинской помощи, обеспечить охрану имущества и регулярно информировать население.","Возложить организацию размещения исключительно на добровольцев, не определяя ответственность органов власти за эвакуацию и необходимые услуги.","Поставить всех эвакуированных на единый учёт без различия медицинских потребностей и предложить им самостоятельно решать вопросы лечения и социальных выплат.","Сосредоточить расходы только на строительстве временной дамбы без расчёта воздействия на соседние территории и без организации помощи эвакуированным.","Объявить возвращение во все подтопленные дома без проверки безопасности и состояния зданий, чтобы сократить расходы на пункты размещения.","Публиковать персональные сведения и адреса всех эвакуированных в открытых социальных сетях для ускорения распределения помощи."]'::jsonb,
effect_plan=jsonb_set(c.effect_plan,'{options}',(
 SELECT jsonb_agg(
 jsonb_set(
   jsonb_set(o.item,'{description}',to_jsonb(CASE WHEN o.item->>'key'='option_1' THEN 'При паводке органы обязаны обеспечить защиту людей, а не ограничиваться одним инженерным сооружением. Правильный вариант объединяет законную эвакуацию, медицинские и социальные услуги, охрану имущества и своевременное информирование. Эти функции соответствуют статье 11 закона № 68-ФЗ; инженерные решения требуют подтверждённых расчётов и не отменяют помощи пострадавшим.'::text ELSE ('["Согласовать безопасную эвакуацию с оперативным штабом, организовать размещение по потребностям граждан, восстановить доступ к выплатам и медицинской помощи, обеспечить охрану имущества и регулярно информировать население.","Возложить организацию размещения исключительно на добровольцев, не определяя ответственность органов власти за эвакуацию и необходимые услуги.","Поставить всех эвакуированных на единый учёт без различия медицинских потребностей и предложить им самостоятельно решать вопросы лечения и социальных выплат.","Сосредоточить расходы только на строительстве временной дамбы без расчёта воздействия на соседние территории и без организации помощи эвакуированным.","Объявить возвращение во все подтопленные дома без проверки безопасности и состояния зданий, чтобы сократить расходы на пункты размещения.","Публиковать персональные сведения и адреса всех эвакуированных в открытых социальных сетях для ускорения распределения помощи."]'::jsonb->>(o.pos::integer-1)) END)),
   '{legal_basis}',to_jsonb('Федеральный закон от 21.12.1994 № 68-ФЗ, статья 11 — эвакуация, информирование, аварийно-спасательные мероприятия и обеспечение защиты населения.'::text)
 ) ORDER BY o.pos)
 FROM jsonb_array_elements(c.effect_plan->'options') WITH ORDINALITY AS o(item,pos)
))
WHERE c.case_key='bank-expanded-serious-07-01';

DO $case$
BEGIN
 IF NOT EXISTS(SELECT 1 FROM public.event_cases WHERE case_key='bank-curated-serious-18' AND effect_plan->>'best_option_key'='option_1' AND jsonb_array_length(decision_options)=5 AND jsonb_array_length(effect_plan->'options')=5)
 THEN RAISE EXCEPTION 'Choice position unexpectedly changed for bank-curated-serious-18'; END IF;
END $case$;
UPDATE public.event_cases AS c
SET title='Благовещенск: плохая дорога затрудняет проезд скорой помощи', situation='20 марта 2025 года прокуратура города Благовещенска Амурской области сообщила о судебном споре из-за состояния участка дороги от улицы Богдана Хмельницкого до строения № 99/1 на той же улице. Проверка установила неудовлетворительное состояние покрытия. Проезд и проход жителей, а также движение машин специального назначения — скорой помощи, полиции и пожарной охраны — были затруднены. Прокуратура указала на бездействие администрации в содержании участка и обратилась в суд.

В предъявленном требовании было предложено привести дорожное покрытие в соответствие с нормативными требованиями, в том числе убрать снежно-ледяные образования и выполнить профилирование проезжей части. Суд удовлетворил заявленные требования. На дату прокурорского сообщения решение ещё не вступило в законную силу, а фактическое исполнение оставалось на контроле. Поэтому неверно утверждать, что ремонт уже окончательно завершён либо что судебное решение стало обязательным к исполнению раньше предусмотренного процессуального момента.

Ситуация требует управленческого решения, направленного на обеспечение доступности проезда при соблюдении дорожных и бюджетных процедур. Следует установить владельца дороги и ответственное подразделение, оценить проходимость для экстренных служб, определить первоочередные безопасные меры, а затем оформить необходимое содержание или ремонт. Если отдельный участок временно небезопасен, об этом должны знать экстренные службы и участники движения.

Статья 17 Федерального закона № 257-ФЗ устанавливает цели содержания автомобильных дорог, включая поддержание безопасных условий движения. Как организовать устранение выявленных препятствий, обеспечить доступ к домам и провести контроль исполнения без произвольного расходования средств и подмены ремонта отчётами?',
source_url='https://epp.genproc.gov.ru/ru/proc_28/mass-media/news/regional/e5664303/',
source_note='Подтверждённые обстоятельства: https://epp.genproc.gov.ru/ru/proc_28/mass-media/news/regional/e5664303/; правовое основание: Федеральный закон от 08.11.2007 № 257-ФЗ, статья 17 — содержание автомобильных дорог и обеспечение безопасных условий движения.',
decision_options='["Проверить владельца дороги и фактическую доступность для спецслужб, определить необходимые безопасные работы по содержанию, оформить финансирование, согласовать при необходимости временную схему проезда и проконтролировать исполнение.","Опубликовать разъяснение, что участок находится на окраине города и потому администрация не несёт обязательств по безопасности движения.","Закрыть проезд всем автомобилям экстренных служб на неопределённый срок без определения альтернативного маршрута.","Переложить все работы на жителей близлежащих домов без проверки владельца дороги и законных обязанностей по её содержанию.","Объявить о полном исполнении решения суда до вступления его в законную силу и без фактического обследования покрытия."]'::jsonb,
effect_plan=jsonb_set(c.effect_plan,'{options}',(
 SELECT jsonb_agg(
 jsonb_set(
   jsonb_set(o.item,'{description}',to_jsonb(CASE WHEN o.item->>'key'='option_1' THEN 'Организатор дорожной деятельности обязан устранить подтверждённые нарушения доступности с учётом безопасности движения и полномочий владельца дороги. Временный проезд экстренных служб, конкретные дорожные работы и подтверждение их исполнения важнее информационных отчётов. Применяется статья 17 закона № 257-ФЗ, а процессуальный статус судебного решения должен отражаться достоверно.'::text ELSE ('["Проверить владельца дороги и фактическую доступность для спецслужб, определить необходимые безопасные работы по содержанию, оформить финансирование, согласовать при необходимости временную схему проезда и проконтролировать исполнение.","Опубликовать разъяснение, что участок находится на окраине города и потому администрация не несёт обязательств по безопасности движения.","Закрыть проезд всем автомобилям экстренных служб на неопределённый срок без определения альтернативного маршрута.","Переложить все работы на жителей близлежащих домов без проверки владельца дороги и законных обязанностей по её содержанию.","Объявить о полном исполнении решения суда до вступления его в законную силу и без фактического обследования покрытия."]'::jsonb->>(o.pos::integer-1)) END)),
   '{legal_basis}',to_jsonb('Федеральный закон от 08.11.2007 № 257-ФЗ, статья 17 — содержание автомобильных дорог и обеспечение безопасных условий движения.'::text)
 ) ORDER BY o.pos)
 FROM jsonb_array_elements(c.effect_plan->'options') WITH ORDINALITY AS o(item,pos)
))
WHERE c.case_key='bank-curated-serious-18';

DO $case$
BEGIN
 IF NOT EXISTS(SELECT 1 FROM public.event_cases WHERE case_key='bank-expanded-serious-01-01' AND effect_plan->>'best_option_key'='option_1' AND jsonb_array_length(decision_options)=6 AND jsonb_array_length(effect_plan->'options')=6)
 THEN RAISE EXCEPTION 'Choice position unexpectedly changed for bank-expanded-serious-01-01'; END IF;
END $case$;
UPDATE public.event_cases AS c
SET title='Челябинск: аварийный дом на улице Якутской и затянувшееся расселение', situation='6 апреля 2026 года управление Генеральной прокуратуры по Уральскому федеральному округу сообщило о мерах по расселению аварийного дома № 6 на улице Якутской в Челябинске. Дом признали аварийным в январе 2024 года, но первоначально расселение планировалось только на 2035 год. Надзорная проверка выявила обрушение чердачного помещения; в одной из квартир образовалась дыра в потолке. Жительнице этой квартиры под контролем прокуратуры предоставили временное помещение маневренного фонда.

Прокурор направил в суд требование сократить срок расселения. Суд его удовлетворил. После этого земельный участок под домом изъяли для муниципальных нужд. По состоянию на 1 апреля 2026 года были завершены мероприятия по расселению семи жилых помещений, а в отношении ещё одного работы продолжались под контролем прокуратуры. Эти сведения позволяют оценивать действия органов власти без выдуманных данных о числе пострадавших семей и без утверждения, что на дату сообщения весь дом уже полностью освобождён.

Для компетентного органа задача включает как немедленное устранение угрозы жизни и здоровью, так и законное решение жилищных прав каждого собственника или нанимателя. Требования для разных категорий жильцов могут различаться; универсальное обещание одинаковой квартиры всем без проверки договора и правового режима жилья неправомерно. Необходимы оценка текущих рисков, временное безопасное размещение при необходимости, инвентаризация прав жителей, подтверждённый график расселения и соблюдение правил предоставления возмещения или жилого помещения.

Статья 32 Жилищного кодекса регулирует обеспечение прав собственников при изъятии помещений, а статья 86 — предоставление жилья нанимателям в установленных случаях. Как сократить опасное ожидание, сохранить законные права жителей и обеспечить контроль исполнения судебного решения?',
source_url='https://epp.genproc.gov.ru/ru/proc_urfo/mass-media/news/main/e8451438/',
source_note='Подтверждённые обстоятельства: https://epp.genproc.gov.ru/ru/proc_urfo/mass-media/news/main/e8451438/; правовое основание: Жилищный кодекс Российской Федерации, статьи 32 и 86 — обеспечение жилищных прав при изъятии и предоставление жилья по социальному найму с учётом правового статуса граждан.',
decision_options='["Немедленно оценить угрозу жильцам и обеспечить необходимые временные безопасные меры, установить правовой статус каждого жилого помещения, выполнить законную процедуру расселения с подтверждёнными сроками и проконтролировать исполнение судебного решения.","Ожидать первоначального срока до 2035 года, поскольку он был указан в прежнем плане, не оценивая опасные дефекты.","Предложить всем жильцам одинаковую денежную сумму без проверки прав собственности, социального найма и установленных гарантий.","Объявить дом расселённым после предоставления маневренного жилья одной семье, не проверив права остальных жителей.","Потребовать от жильцов самостоятельно сносить аварийный дом и приобретать жильё за свой счёт, не применяя процедуры жилищного законодательства.","Отложить оценку угрозы до завершения всех судебных споров, оставив людей в помещениях с подтверждёнными опасными дефектами."]'::jsonb,
effect_plan=jsonb_set(c.effect_plan,'{options}',(
 SELECT jsonb_agg(
 jsonb_set(
   jsonb_set(o.item,'{description}',to_jsonb(CASE WHEN o.item->>'key'='option_1' THEN 'Опасное состояние здания требует своевременных защитных мер, а постоянное расселение — соблюдения разных жилищных гарантий собственников и нанимателей. По статьям 32 и 86 ЖК РФ необходимо установить правовой режим помещений и соответствующий способ защиты права. Судебное решение и фактические сроки исполнения должны контролироваться; маневренный фонд не заменяет окончательного решения по всем жильцам.'::text ELSE ('["Немедленно оценить угрозу жильцам и обеспечить необходимые временные безопасные меры, установить правовой статус каждого жилого помещения, выполнить законную процедуру расселения с подтверждёнными сроками и проконтролировать исполнение судебного решения.","Ожидать первоначального срока до 2035 года, поскольку он был указан в прежнем плане, не оценивая опасные дефекты.","Предложить всем жильцам одинаковую денежную сумму без проверки прав собственности, социального найма и установленных гарантий.","Объявить дом расселённым после предоставления маневренного жилья одной семье, не проверив права остальных жителей.","Потребовать от жильцов самостоятельно сносить аварийный дом и приобретать жильё за свой счёт, не применяя процедуры жилищного законодательства.","Отложить оценку угрозы до завершения всех судебных споров, оставив людей в помещениях с подтверждёнными опасными дефектами."]'::jsonb->>(o.pos::integer-1)) END)),
   '{legal_basis}',to_jsonb('Жилищный кодекс Российской Федерации, статьи 32 и 86 — обеспечение жилищных прав при изъятии и предоставление жилья по социальному найму с учётом правового статуса граждан.'::text)
 ) ORDER BY o.pos)
 FROM jsonb_array_elements(c.effect_plan->'options') WITH ORDINALITY AS o(item,pos)
))
WHERE c.case_key='bank-expanded-serious-01-01';

DO $check$ BEGIN
 IF (SELECT count(*) FROM public.event_cases c WHERE c.case_key IN ('bank-expanded-serious-05-01','bank-expanded-serious-22-01','bank-curated-serious-02','bank-expanded-serious-07-01','bank-curated-serious-18','bank-expanded-serious-01-01') AND c.source_url LIKE 'https://%'
 AND jsonb_array_length(c.decision_options)=jsonb_array_length(c.effect_plan->'options')
 AND EXISTS(SELECT 1 FROM jsonb_array_elements(c.effect_plan->'options') o WHERE o->>'key'=c.effect_plan->>'best_option_key' AND o->>'legal_basis' ~ '(Федеральный закон|Жилищный кодекс)'))<>6
 THEN RAISE EXCEPTION 'Post-edit quality check failed'; END IF;
END $check$;